#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}
# ──────────────────────────────────────────────────────────────────────────
# STAGES: the realtime Worker (#157, ADR 0012). Deploys the staging and the
# production Worker once, gives each its two room secrets, and wires the app
# (Vercel) and the deploy workflow (GitHub) to them. Nothing is written to
# the repo or the local .env. The room secrets live only in this run and in the
# places they are set, so a re-run makes new ones and sets them everywhere again.
# --dry-run walks every stage without opening a browser, calling Cloudflare,
# GitHub or Vercel, or needing any access.
# ──────────────────────────────────────────────────────────────────────────

# Set by --dry-run: pages are printed, not opened; values are placeholders;
# nothing external is called.
DRY_RUN=0
ROOT=""
CF_ACCOUNT_ID=""     # the Cloudflare account that owns the Workers
CF_API_TOKEN=""      # "Edit Cloudflare Workers" token, scoped to that account
STAGING_TOKEN_SECRET=""     # ROOM_TOKEN_SECRET of the staging Worker and the staging app
STAGING_INTERNAL_SECRET=""  # ROOM_INTERNAL_SECRET, likewise
PRODUCTION_TOKEN_SECRET=""
PRODUCTION_INTERNAL_SECRET=""
STAGING_URL=""       # the *.workers.dev address wrangler printed
PRODUCTION_URL=""
VERCEL_SET=()        # "NAME for ENV" entries written this run
VERCEL_ERR=""        # stderr of the last vercel env add, never the value
WRANGLER_OUT=""      # output of the last wrangler call, never a secret

# page URL opens a page, or only prints it in a dry run.
page() {
  if (( DRY_RUN )); then
    printf '  %s○ dry run, not opening%s %s\n' "$DIM" "$RESET" "$1"
  else
    open_url "$1"
  fi
}

# need KIND KEY "Prompt" REGEX "hint": asks until the value matches REGEX, then
# sets $KEY. KIND is visible or secret (hidden input). Three tries, then stop.
# A dry run takes a placeholder so the walk-through needs no input.
need() {
  local kind="$1" key="$2" prompt="$3" regex="$4" hint="$5" tries=0 value
  while :; do
    if [[ "$kind" == secret ]]; then ask_secret "$key" "$prompt" || true
    else ask "$key" "$prompt" || true; fi
    value="${!key:-}"
    # Trim the ends only (a pasted newline or space); inner spaces stay and fail REGEX.
    value="${value#"${value%%[![:space:]]*}"}"
    value="${value%"${value##*[![:space:]]}"}"
    printf -v "$key" '%s' "$value"
    if (( DRY_RUN )); then
      [[ -n "$value" ]] || printf -v "$key" '%s' '<dry-run>'
      note "dry run: $key is a placeholder"
      return 0
    fi
    if [[ "$value" =~ $regex ]]; then
      printf '  %s✓ captured%s %s\n' "$GREEN" "$RESET" "$key"
      return 0
    fi
    tries=$((tries + 1))
    if (( tries >= 3 )); then
      warn "$key is still empty or malformed. Stopping; re-run the wizard."
      exit 1
    fi
    warn "that doesn't look right ($hint). Try again."
  done
}

# yes_or_stop "question" is a gate: a no stops the wizard, so later stages never
# run on a token or account that isn't ready yet.
yes_or_stop() {
  if (( DRY_RUN )); then
    note "dry run: assuming yes: $1"
    return 0
  fi
  confirm "$1" || {
    warn "Finish that step first, then re-run the wizard."
    exit 1
  }
}

# new_key prints a random 32-byte key in base64.
new_key() {
  if command -v openssl >/dev/null 2>&1; then
    openssl rand -base64 32
  else
    node -e "process.stdout.write(require('crypto').randomBytes(32).toString('base64'))"
  fi
}

# gh_secret NAME VALUE sets a GitHub Actions secret, or only says so in a dry run.
gh_secret() {
  if (( DRY_RUN )); then
    printf '  %s○ dry run, would run%s gh secret set %s (value on stdin)\n' "$DIM" "$RESET" "$1"
    return 0
  fi
  set_secret "$1" "$2"
}

# wrangler ARGS... runs wrangler from realtime/ as the Workers token. The token
# is in that one process's environment, never in argv or in this shell's.
wrangler() {
  ( cd "$ROOT/realtime" && CLOUDFLARE_API_TOKEN="$CF_API_TOKEN" CLOUDFLARE_ACCOUNT_ID="$CF_ACCOUNT_ID" pnpm exec wrangler "$@" )
}

# deploy_worker ENV VARIABLE deploys the Worker of ENV and sets $VARIABLE to its
# *.workers.dev address. The address comes from wrangler's output; if it is not
# in there, you paste it.
deploy_worker() {
  local env="$1" key="$2" log url
  if (( DRY_RUN )); then
    printf '  %s○ dry run, would run%s pnpm --dir realtime run deploy:%s\n' "$DIM" "$RESET" "$env"
    printf -v "$key" '%s' "https://compies-rt-${env}.example.workers.dev"
    return 0
  fi
  log=$(mktemp)
  if ! ( cd "$ROOT/realtime" && CLOUDFLARE_API_TOKEN="$CF_API_TOKEN" CLOUDFLARE_ACCOUNT_ID="$CF_ACCOUNT_ID" pnpm run "deploy:$env" ) 2>&1 | tee "$log"; then
    rm -f "$log"
    warn "The $env deploy failed. Fix what wrangler says above, then re-run the wizard."
    exit 1
  fi
  url=$(grep -oE 'https://[A-Za-z0-9.-]+\.workers\.dev' "$log" | head -n1 || true)
  rm -f "$log"
  if [[ -n "$url" ]]; then
    printf -v "$key" '%s' "$url"
    printf '  %s✓ deployed%s the %s Worker at %s\n' "$GREEN" "$RESET" "$env" "$url"
  else
    warn "Could not find the *.workers.dev address in wrangler's output."
    need visible "$key" "Paste the address of the $env Worker:" '^https://[A-Za-z0-9.-]+\.workers\.dev/?$' "https://<name>.<subdomain>.workers.dev"
  fi
  printf -v "$key" '%s' "${!key%/}"
}

# worker_secret ENV NAME VALUE puts a secret on the Worker of ENV. The value goes
# in on stdin, so it never shows up in argv, output or shell history.
worker_secret() {
  local env="$1" name="$2" value="$3"
  if (( DRY_RUN )); then
    printf '  %s○ dry run, would run%s wrangler secret put %s --env %s (value on stdin)\n' "$DIM" "$RESET" "$name" "$env"
    return 0
  fi
  if WRANGLER_OUT=$(printf '%s' "$value" | wrangler secret put "$name" --env "$env" 2>&1); then
    printf '  %s✓ set%s %s on the %s Worker\n' "$GREEN" "$RESET" "$name" "$env"
  else
    SKIPPED+=("Worker secret $name ($env): cd realtime && pnpm exec wrangler secret put $name --env $env")
    warn "couldn't set $name on the $env Worker. Wrangler said: ${WRANGLER_OUT:-nothing}"
  fi
}

# _vercel_add NAME VALUE ENVIRONMENT [BRANCH] adds one variable. The value goes
# in on stdin, so it never shows up in argv, output or shell history.
_vercel_add() {
  VERCEL_ERR=$(printf '%s' "$2" | vercel env add "$1" "$3" ${4:+"$4"} 2>&1 >/dev/null)
}

# vercel_set NAME VALUE ENVIRONMENT [BRANCH] writes NAME to Vercel. An existing
# variable is replaced after you confirm. Only the name and target are printed.
vercel_set() {
  local name="$1" value="$2" target="$3" branch="${4:-}" label
  label="$name for $target${branch:+ (branch $branch)}"
  if (( DRY_RUN )); then
    printf '  %s○ dry run, would run%s vercel env add %s %s%s (value on stdin)\n' \
      "$DIM" "$RESET" "$name" "$target" "${branch:+ $branch}"
    VERCEL_SET+=("$label")
    return 0
  fi
  if _vercel_add "$name" "$value" "$target" "$branch"; then
    printf '  %s✓ set%s %s\n' "$GREEN" "$RESET" "$label"
    VERCEL_SET+=("$label")
    return 0
  fi
  if [[ "$VERCEL_ERR" == *"already exists"* ]] && confirm "$label already exists. Replace it?"; then
    if vercel env rm "$name" "$target" ${branch:+"$branch"} --yes >/dev/null 2>&1 \
      && _vercel_add "$name" "$value" "$target" "$branch"; then
      printf '  %s✓ replaced%s %s\n' "$GREEN" "$RESET" "$label"
      VERCEL_SET+=("$label")
      return 0
    fi
  fi
  SKIPPED+=("Vercel $name for $target${branch:+ (branch $branch)}: set it in the dashboard")
  warn "couldn't set $label. Vercel said: ${VERCEL_ERR:-nothing}"
}

# vercel_by_hand is the fallback without the Vercel CLI: the same variables,
# typed into the dashboard. The wizard sets the GitHub and Worker side only.
vercel_by_hand() {
  warn "Without the Vercel CLI this wizard can't set the app's variables. Do it by hand, after the wizard:"
  step "Open https://vercel.com/dashboard, then the COMPIES project, then Settings → Environment Variables."
  step "Production: REALTIME_URL (the production Worker address), ROOM_TOKEN_SECRET, ROOM_INTERNAL_SECRET."
  step "Preview, limited to the git branch staging: the same three, with the staging Worker address and the staging secrets."
  note "The secrets must equal the ones on the Worker. Re-run the wizard with the Vercel CLI installed to have them set for you."
  exit 0
}

run_wizard() {

for arg in "$@"; do
  case "$arg" in
    --dry-run) DRY_RUN=1 ;;
    -h|--help)
      printf 'Usage: scripts/wizards/realtime-setup.sh [--dry-run]\n'
      printf '  --dry-run  walk every stage without opening browsers or calling Cloudflare, GitHub or Vercel\n'
      exit 0 ;;
    *) printf 'Unknown option: %s\n' "$arg" >&2; exit 2 ;;
  esac
done

# Vercel links and the realtime/ folder are relative to the repo root, wherever you start from.
ROOT=$(cd "$(dirname "$0")/../.." && pwd)
cd "$ROOT"

TOTAL_STAGES=10

banner "COMPIES: the realtime Worker (#157)"

# ── Stage 1: tools ────────────────────────────────────────────────────────
stage "Tools: GitHub, Vercel and the Worker's dependencies"
say "This needs the GitHub CLI (gh) signed in, the Vercel CLI signed in and linked, and the Worker's dependencies installed."
if (( DRY_RUN )); then
  note "dry run: would check gh, the Vercel CLI, the .vercel/ link and run pnpm --dir realtime install"
else
  if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
    warn "The GitHub CLI is missing or not signed in, so the GitHub secrets can't be set."
    say "Install it from https://cli.github.com, run gh auth login, then re-run the wizard."
    exit 1
  fi
  printf '  %s✓%s gh is signed in\n' "$GREEN" "$RESET"
  if ! command -v vercel >/dev/null 2>&1; then
    warn "The Vercel CLI is not installed."
    if confirm "Install it now with npm (npm install -g vercel)?"; then
      npm install -g vercel || warn "npm could not install the Vercel CLI"
    fi
  fi
  command -v vercel >/dev/null 2>&1 || vercel_by_hand
  # A CLI that can't start would otherwise read as "not signed in" below.
  if ! vercel --version >/dev/null 2>&1; then
    warn "The Vercel CLI at $(command -v vercel) does not run in this shell."
    if [[ -n "${WSL_DISTRO_NAME:-}" ]]; then
      note "This is WSL's bash: it finds the Windows Vercel CLI, but not the Windows node it needs."
      note "Run the wizard from Git Bash instead. From PowerShell:"
      note '  & "C:\Program Files\Git\bin\bash.exe" scripts/wizards/realtime-setup.sh'
    fi
    exit 1
  fi
  if ! vercel whoami >/dev/null 2>&1; then
    say "Sign in to Vercel. The CLI opens a browser or prints a link to open."
    vercel login || true
  fi
  vercel whoami >/dev/null 2>&1 || { warn "Still not signed in to Vercel. Run vercel login, then re-run the wizard."; exit 1; }
  printf '  %s✓%s signed in to Vercel as %s\n' "$GREEN" "$RESET" "$(vercel whoami 2>/dev/null | tail -n1)"
  if [[ ! -f "$ROOT/.vercel/project.json" ]]; then
    say "Link this checkout to the existing COMPIES project. Pick the team that owns it."
    vercel link || { warn "vercel link did not finish. Re-run the wizard after linking."; exit 1; }
  fi
  printf '  %s✓%s the checkout is linked to the Vercel project\n' "$GREEN" "$RESET"
  say "Installing the Worker's dependencies (wrangler)."
  pnpm --dir realtime install --frozen-lockfile || { warn "pnpm install in realtime/ failed."; exit 1; }
fi
pause "Press Enter to continue."

# ── Stage 2: Cloudflare account ───────────────────────────────────────────
stage "Cloudflare: the Account ID and the workers.dev address"
say "Use the same Cloudflare account as for the image buckets (R2)."
page "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "In the left sidebar, open Workers & Pages. The Account ID is shown on the right side of that page; copy it."
step "If Cloudflare asks you to choose a workers.dev subdomain, choose one. It becomes part of both Worker addresses."
note "The Workers Free plan is enough. Durable Objects on the free plan use SQLite, which is what the rooms use."
need visible CF_ACCOUNT_ID "Paste the Account ID:" '^[0-9a-fA-F]{32}$' "32 hexadecimal characters"

# ── Stage 3: API token ────────────────────────────────────────────────────
stage "Cloudflare: an API token for deploying Workers"
say "One token lets GitHub Actions and this wizard deploy the Workers."
page "https://dash.cloudflare.com/profile/api-tokens"
step "Click 'Create Token'. Next to the template 'Edit Cloudflare Workers', click 'Use template'."
step "Name: compies-workers (any name works)."
step "Account Resources: Include → your account (the one whose ID you pasted). Zone Resources: leave the template's choice, or pick your zone."
step "Click 'Continue to summary', then 'Create Token'."
warn "Cloudflare shows the token once. Keep the page open until it is copied."
need secret CF_API_TOKEN "Paste the API token (input stays hidden):" '^[[:graph:]]{20,}$' "one word without spaces"
if (( DRY_RUN )); then
  note "dry run: would verify the token with Cloudflare"
else
  # The token goes in through curl's config on stdin, not through argv.
  if printf 'header = "Authorization: Bearer %s"\n' "$CF_API_TOKEN" \
    | curl -sS --max-time 20 -K - https://api.cloudflare.com/client/v4/user/tokens/verify 2>/dev/null \
    | grep -q '"status":"active"'; then
    printf '  %s✓%s Cloudflare says the token is active\n' "$GREEN" "$RESET"
  else
    warn "Cloudflare did not confirm the token as active."
    yes_or_stop "Continue anyway?"
  fi
fi
pause "Press Enter to continue."

# ── Stage 4: GitHub secrets and the room keys ─────────────────────────────
stage "GitHub: secrets for the deploy workflow, and the room keys"
say "Staging and production get different room keys. They are made now and set in the next stages."
cd "$ROOT"
gh_secret CLOUDFLARE_API_TOKEN "$CF_API_TOKEN"
gh_secret CLOUDFLARE_ACCOUNT_ID "$CF_ACCOUNT_ID"
STAGING_TOKEN_SECRET=$(new_key)
STAGING_INTERNAL_SECRET=$(new_key)
PRODUCTION_TOKEN_SECRET=$(new_key)
PRODUCTION_INTERNAL_SECRET=$(new_key)
printf '  %s✓ made%s four room keys (ROOM_TOKEN_SECRET and ROOM_INTERNAL_SECRET, for staging and for production)\n' "$GREEN" "$RESET"
# The production workflow signs its game-day check with the production key the app has.
gh_secret ROOM_INTERNAL_SECRET_PRODUCTION "$PRODUCTION_INTERNAL_SECRET"
pause "Press Enter to continue."

# ── Stage 5: staging Worker ───────────────────────────────────────────────
stage "Staging Worker: first deploy and secrets"
say "Deploys compies-rt-staging, then gives it its two secrets."
deploy_worker staging STAGING_URL
worker_secret staging ROOM_TOKEN_SECRET "$STAGING_TOKEN_SECRET"
worker_secret staging ROOM_INTERNAL_SECRET "$STAGING_INTERNAL_SECRET"
pause "Press Enter to continue."

# ── Stage 6: production Worker ────────────────────────────────────────────
stage "Production Worker: first deploy and secrets"
say "Deploys compies-rt, then gives it its two secrets. Nobody is connected to it yet, so nothing is dropped."
yes_or_stop "Deploy the production Worker now?"
deploy_worker production PRODUCTION_URL
worker_secret production ROOM_TOKEN_SECRET "$PRODUCTION_TOKEN_SECRET"
worker_secret production ROOM_INTERNAL_SECRET "$PRODUCTION_INTERNAL_SECRET"
pause "Press Enter to continue."

# ── Stage 7: Vercel production ────────────────────────────────────────────
stage "Vercel: variables for production (branch main)"
say "The app needs the Worker's address and the same two secrets the Worker has."
vercel_set REALTIME_URL "$PRODUCTION_URL" production
vercel_set ROOM_TOKEN_SECRET "$PRODUCTION_TOKEN_SECRET" production
vercel_set ROOM_INTERNAL_SECRET "$PRODUCTION_INTERNAL_SECRET" production
pause "Press Enter to continue."

# ── Stage 8: Vercel staging branch ────────────────────────────────────────
stage "Vercel: variables for the staging branch (Preview)"
say "Writes the Preview environment, limited to the git branch staging (ADR 0007)."
vercel_set REALTIME_URL "$STAGING_URL" preview staging
vercel_set ROOM_TOKEN_SECRET "$STAGING_TOKEN_SECRET" preview staging
vercel_set ROOM_INTERNAL_SECRET "$STAGING_INTERNAL_SECRET" preview staging
pause "Press Enter to continue."

# ── Stage 9: redeploy ─────────────────────────────────────────────────────
stage "Vercel: redeploy staging"
say "Vercel applies new variables to new deployments only, and REALTIME_URL is read at build time."
page "https://vercel.com/dashboard"
step "Open the COMPIES project, then Deployments."
step "Find the latest deployment of the branch staging, open its menu (⋯) and choose Redeploy."
step "Leave 'Use existing Build Cache' off, then confirm."
note "Production picks the variables up with its next deployment, which is the 1.4 Release."
pause "Press Enter once the staging deployment is Ready."

# ── Stage 10: check and finish ────────────────────────────────────────────
stage "Check the result"
if (( DRY_RUN )); then
  note "dry run: would GET both Workers and call the production deploy check, signed"
else
  # A plain GET has no room behind it: 404 or 403 means the Worker answers. Only a failed connection is a problem.
  for env in staging production; do
    url="$STAGING_URL"; [[ "$env" == production ]] && url="$PRODUCTION_URL"
    if code=$(curl -sS -o /dev/null -w '%{http_code}' --max-time 20 "$url/" 2>/dev/null); then
      printf '  %s✓%s the %s Worker answers (HTTP %s)\n' "$GREEN" "$RESET" "$env" "$code"
    else
      SKIPPED+=("the $env Worker at $url did not answer; a new workers.dev address can take a minute to resolve")
      warn "the $env Worker at $url did not answer"
    fi
  done
  # The same signed call the deploy workflow makes. A game day still counts as an answer.
  # The staging-to-production Release brings the endpoint to the production app: a 404 before that is expected.
  check=$(ROOM_INTERNAL_SECRET="$PRODUCTION_INTERNAL_SECRET" node "$ROOT/realtime/scripts/deploy-check.mjs" 2>&1) && check_ok=1 || check_ok=0
  if (( check_ok )) || [[ "$check" == *"game day"* ]]; then
    printf '  %s✓%s the production app answers the signed deploy check\n' "$GREEN" "$RESET"
  elif [[ "$check" == *"answered 404"* ]]; then
    note "the production app has no deploy check yet: it arrives with the 1.4 Release. After the Release, run the check by hand (docs/agents/release.md, No game days)."
  else
    SKIPPED+=("the signed deploy check against production failed: $check")
    warn "the signed deploy check against production failed: $check"
  fi
fi
if (( ${#VERCEL_SET[@]} )); then
  verb="set"
  (( DRY_RUN )) && verb="would set"
  printf '\n'
  for entry in "${VERCEL_SET[@]}"; do note "$verb: $entry"; done
fi
say "Staging: open an Event in two browsers on https://staging.compies.christried.me. A Vote shows in the other at once."
say "From now on a push to staging deploys the staging Worker, and a push to main the production Worker (the Realtime deploy workflow)."
pause "Press Enter to finish."

finish
}

run_wizard "$@"; exit
